BEGIN TRANSACTION READ ONLY; SELECT current_setting('transaction_read_only') AS read_only, clock_timestamp() AT TIME ZONE 'UTC' AS captured_at_utc, count(*) AS matching_public_overloads, coalesce(jsonb_agg(jsonb_build_object('schema',n.nspname,'name',p.proname,'identity_arguments',pg_get_function_identity_arguments(p.oid),'security_definer',p.prosecdef,'acl',p.proacl::text) ORDER BY p.proname,pg_get_function_identity_arguments(p.oid)), '[]'::jsonb) AS functions FROM pg_proc p JOIN pg_namespace n ON n.oid=p.pronamespace WHERE n.nspname='public' AND p.proname IN ('create_catalog_calculator_with_audit','record_calculator_qa_decision','assign_calculator_reviewer','transition_calculator_with_audit','prepare_catalog_inventory_drafts','publish_calculator_batch_with_audit_v1'); COMMIT;
